export class Entity {
    /** 
     * 32-bit bitmask representing which layers this entity belongs to.
     * Default: 1 (Layer 0).
     */
    public layerMask: number = 1;

    /** 
     * Indicates whether this entity is flagged as a UI element.
     * Default: false.
     */
    public isUI: boolean = false;

    public static readonly UI_LAYER = 31;
}

export class Camera extends Entity {
    /**
     * Bitmask controlling which layers this camera renders.
     * Default: 1 (Layer 0 only).
     */
    public cullingMask: number = 1;
}

