import { Scene, SDFText, Color, ThreeDAxes, OrbitCameraController, Vec3 } from "retiam";

export class My3DScene extends Scene {
    public async run() {
        // 1. 3D Camera Controls (operates on default_view / Layer 0)
        this.camera.position.set([0, 5, 10]);
        new OrbitCameraController(this, this.camera, new Vec3(0, 0, 0));

        // 2. Add 3D World Geometry (Layer 0 by default)
        const axes = new ThreeDAxes({ width: 10, height: 5, depth: 10 });
        this.add(axes);

        // 3. Add Screen UI Title (Layer 31)
        const title = new SDFText("3D Surface Visualizer", { fontSize: 0.8 });
        title.setAsUI();
        title.transform.position.set([-7.5, 4.0, 0]); // Top-left corner
        title.paint.fill = new Color(1, 1, 1, 1);
        this.add(title);
    }
}

